    static let motorcycleChaseAgain2 = SmallCases.make(
        key: "story.followup.motorcycleChaseAgain2",
        category: .traffic,
        headlines: ["Rider Pops Wheelie Through School Crosswalk, Bystander Video Shows", "Rider From Earlier Chase Case Cited for Stunt Riding"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 21...40,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a bystander filmed a rider on a sport bike popping a wheelie through a crosswalk beside an elementary school at pickup time. Crossing guards pulled children back. The tag traced to {D}. {DL} says a friend rode the bike that afternoon.",
        state: [E(.video, 3, "Bystander Video", "A rider lifts the front wheel through the crosswalk as children step back."), E(.document, 2, "Tag Registration", "The tag on the bike is registered to {D}.")],
        defense: [E(.statement, 1, "Friend Rode", "{DL} says a friend borrowed the bike that afternoon.")],
        role: "Crossing guard",
        exam: [.direct("What is your job?", "\"I'm a crossing guard at an elementary school, and I help children cross the street at pickup time.\""), .direct("What happened that afternoon?", "\"A motorcycle came down the road, and the rider popped a wheelie right through our crosswalk as children were stepping off the curb.\""), .direct("How fast was the motorcycle?", "\"Faster than the limit by far, at least forty in a twenty-mile zone, and the front wheel was in the air.\""), .direct("What did you do?", "\"I pulled several children back from the curb and shouted. I thought a child was going to be hit.\""), .direct("What does the bystander's video show?", "\"A sport bike lifting the front wheel through the crosswalk, with the children stepping back just in time.\""), .direct("Who owns the bike?", "\"The tag on the bike is registered to {DL}, according to the records.\""), .cross("You couldn't see the rider's face?", "\"No, the rider wore a helmet and a jacket.\""), .cross("No child was hurt?", "\"No, but one child cried, and parents were upset.\""), .cross("The bike didn't stop?", "\"No, it kept going, and I heard it for another block.\""), .cross("The tag was clear on the video?", "\"Yes, the tag was clear on the video, and the video is a good one.\""), .cross("{DL} says a friend rode it?", "\"That's what {D.he} says, but I wasn't there to see.\"")],
        theory: ("{D} rode recklessly past a school again.", "A friend on a borrowed bike."),
        allocution: "\"A friend rode my bike that afternoon, and I never popped a wheelie in front of that school. I should have known better than to lend it. I've been in this courtroom before about a motorcycle, and I'm sorry for the scare to the crossing guards and children.\"",
        truths: ("{DL} had a prior case in this court.", "The friend posted the clip of the ride and tagged {DL}'s bike."),
        defendant: [.direct("Were you riding the motorcycle?", "\"No. A friend borrowed it that afternoon. I wasn't there, and I didn't know what he did.\""), .direct("Who is the friend?", "\"A man I've known for years. I'll give his name to the deputy.\""), .direct("Why did you lend the bike?", "\"He asked, and I trusted him. I told him to be careful.\""), .direct("Where were you that afternoon?", "\"At work, across town. My supervisor can confirm it.\""), .direct("What did you do when you found out?", "\"I called my friend and told him he'd put kids at risk. He said he was sorry.\""), .direct("What would you tell the guard and the children?", "\"I'm sorry for the scare. I'll never lend my bike again.\""), .cross("You have been cited for stunt riding before, haven't you?", "\"Yes, and I told the court I'd stop. I still lent the bike to someone who does it.\""), .cross("The bike is registered to you?", "\"It is registered to me, and I'm responsible for it, even when I lend it.\""), .cross("You can prove you were at work?", "\"Yes, I was at work that afternoon, and I can show you my time card.\""), .cross("You'll name your friend?", "\"Yes, I'll give the deputy my friend's name and number today, without delay.\""), .cross("You'll sell the motorcycle?", "\"If the court says so, yes, I'll sell the motorcycle and never ride again.\"")],
        openings: ("A crossing guard who helps children cross the street at pickup time saw a motorcycle come down the road and the rider pop a wheelie through the crosswalk as children were stepping off the curb, and a bystander filmed it, and the tag traced to {D}, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say a friend rode the bike that afternoon, and {D} was not the rider. A tag shows an owner, not a rider."),
        closings: ("The video shows a rider popping a wheelie through a crosswalk as children stepped off the curb, the tag traces to {D}, and with {PRIOR} already on {D.his} record, {DL} knew exactly what that crosswalk is.", "A friend who borrowed the bike is the rider. The State must prove {D} was the man on the motorcycle, and the video shows a helmet and no face."),
