        mood: .indifferent)

    static let dopeHouseTrailerAgain2 = SmallCases.make(
        key: "story.followup.dopeHouseTrailerAgain2",
        category: .drugs,
        headlines: ["Pharmacist Spots Altered Prescription From Trailer Park Resident", "Doctor's Office Says the Script Was Changed"],
        law: "prescriptionFraud",
        spec: "Obtained a controlled substance by fraud or forgery, on {DATE}.",
        ages: 24...58,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a pharmacist noticed that a prescription for 30 tablets of oxycodone had been changed to 90. The doctor's office had never approved the change. {DL} was waiting at the counter. {DL} says a friend dropped off the paper.",
        state: [E(.document, 3, "Altered Script", "The quantity was changed from 30 to 90 in a different ink."), E(.statement, 2, "Pharmacist", "{DL} presented the script and said, \"Just fill it.\"")],
        defense: [E(.statement, 1, "Dropped Off", "{DL} says a friend left the paper at the trailer.")],
        role: "Pharmacist",
        exam: [.direct("What is your job?", "\"I'm a pharmacist, and I fill prescriptions for controlled medications and check them for signs of tampering.\""), .direct("What did you notice?", "\"A prescription for thirty tablets of oxycodone that had been changed to ninety, in what looked like a different ink.\""), .direct("How did you know it was changed?", "\"The zero in the ninety was written over a smudge, and the ink was darker than the rest of the writing.\""), .direct("What did you do?", "\"I called the doctor's office, and the nurse said the original prescription was for thirty tablets and had never been changed.\""), .direct("Who presented the prescription?", "\"{DL}, who was waiting at the counter, and who said, 'Just fill it.'\""), .direct("What did {DL} say?", "\"{D.He} said a friend left the paper at the trailer and asked {D.him} to fill it.\""), .cross("{DL} didn't fill it?", "\"No, I refused to fill it, and {D.he} left the store without the pills.\""), .cross("{DL} was polite?", "\"Impatient, but not threatening. {D.He} wanted it done quickly, but didn't raise {D.his} voice.\""), .cross("{DL} has a legitimate prescription history?", "\"Not for opioids that I could find in the pharmacy's records, going back several years.\""), .cross("The doctor didn't write the change?", "\"Correct, the doctor's office confirmed that it never approved a change to ninety.\""), .cross("{DL} didn't flee?", "\"{D.He} didn't flee, and {D.he} stayed until I called the deputy.\"")],
        theory: ("{D} altered a script for more pills.", "A paper left by a friend."),
        allocution: "\"I should have asked questions. A friend dropped off that paper, and I stood at the pharmacy counter waiting for it. I never changed the number. I'm sorry to the pharmacist for the trouble.\"",
        truths: ("{DL} had a prior case in this court.", "The friend's handwriting matches the change."),
        defendant: [.direct("Did you change the prescription?", "\"No. A friend left the paper at my trailer and asked me to fill it. I never touched the numbers.\""), .direct("Who is the friend?", "\"A man I know from the neighborhood. He said he was in pain and couldn't come himself.\""), .direct("Did you know it had been changed?", "\"No. I assumed it was a real prescription. It looked official to me.\""), .direct("Why did you say 'Just fill it'?", "\"I was in a hurry and didn't want to wait. I wasn't trying to pressure anyone.\""), .direct("What did you do when the pharmacist refused?", "\"I put the paper down and left. I didn't argue.\""), .direct("What would you tell the pharmacist?", "\"I'm sorry for the trouble. I didn't know the paper was changed.\""), .cross("You've been convicted of a prescription offense before, haven't you?", "\"Yes, and I told the court I'd never go near one. I should have refused.\""), .cross("You presented a paper that was changed from thirty to ninety?", "\"I did, and I can't explain how it was changed.\""), .cross("You'd do a favor for a friend like that without asking questions?", "\"I did hand over that paper, and I regret that I didn't ask more questions.\""), .cross("You'll give the deputy your friend's name?", "\"Yes, I'll give the deputy my friend's name and everything I know about how that paper reached me.\""), .cross("You'll stay out of that pharmacy?", "\"Yes. I'll stay out of that pharmacy.\"")],
        openings: ("A pharmacist who fills controlled prescriptions and checks them for tampering noticed a prescription for thirty tablets of oxycodone that had been changed to ninety in what looked like a different ink, and the doctor's office never approved the change, and {D} was waiting at the counter, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say a friend dropped off the paper at the trailer, and {D} brought it in without knowing it had been changed. {D} did not alter anything."),
        closings: ("The doctor's office never approved the change, {D} waited at the counter, and having faced {PRIOR} before, {DL} understood exactly how a changed prescription is caught.", "A friend's paper looks like any paper. The State must prove {D} knew the quantity had been altered, and the ink on that paper was never tied to {D}'s hand."),
        timeline: [(-3, "The doctor writes the script."), (0, "The pharmacy counter."), (7, "Charges.")],
        identified: "A pharmacist caught the change.",
        mood: .indifferent)

    static let parkingDeckRobberyAgain2 = SmallCases.make(
        key: "story.followup.parkingDeckRobberyAgain2",
        category: .property,
        headlines: ["Power Tools Walked Out of Hardware Store in Duffel Bag", "Deck Robbery Defendant Faces Shoplifting Charge"],
        law: "larcenyMerchant",
        threshold: 6,
        spec: "Took merchandise valued at $1,260 from {V}, a hardware store, on {DATE}.",
        ages: 19...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a hardware store's security camera showed a man load four cordless drills into a duffel bag and leave without paying. Loss prevention followed {D} to the lot. {DL} says the drills were bought with a gift card and the receipt was lost.",
        state: [E(.video, 3, "Store Camera", "{D} fills a duffel with four drills and walks out through the garden entrance."), E(.document, 3, "Inventory Count", "Four drills valued at $1,260 are missing and match the bag.")],
        defense: [E(.statement, 1, "Gift Card", "{DL} says {D.he} paid with a gift card.")],
        role: "Loss prevention officer",
        exam: [.direct("What is your position?", "\"I'm a loss prevention officer at a hardware store, and I watch for theft on the floor and the cameras.\""), .direct("What did you see?", "\"A man filled a duffel bag with four cordless drills, walked through the garden entrance, and left without paying.\""), .direct("What does the store camera show?", "\"{DL} taking drills from a display, one by one, placing them in a duffel, and walking out through the garden door.\""), .direct("What was the value?", "\"Twelve hundred sixty dollars, which is the retail price of four of our top drills.\""), .direct("What did you do?", "\"I followed {DL} to the parking lot and asked {D.him} to open the bag. {D.He} refused at first.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} paid with a gift card, but no card was used at any register.\""), .cross("The inventory count shows the drills are missing?", "\"Yes, four drills are missing, and their size and weight match the bag exactly.\""), .cross("{DL} didn't have a receipt?", "\"No, {D.he} had no receipt, and said that it was somewhere in the car.\""), .cross("The gift card claim hasn't been verified?", "\"We checked, and no gift card was used at any register.\""), .cross("{DL} didn't run?", "\"No, {D.he} didn't run. {D.He} stood in the lot until I reached {D.him}.\""), .cross("The drills were recovered?", "\"Yes, all four drills were recovered from the duffel bag in the parking lot.\"")],
        theory: ("{D} stole drills from a store.", "A gift card and a lost receipt."),
        allocution: "\"I'm sorry for taking them. I bought those drills with a gift card and lost the receipt, and I walked out with the bag anyway. I've been in this courtroom before about a store, and I know that's no excuse. I'll pay for the drills today.\"",
        truths: ("{DL} had a prior case in this court.", "The gift card was used earlier that week at another store."),
        defendant: [.direct("Did you take the drills?", "\"I put four drills in my bag, but I thought I'd paid for them with a gift card. I got confused.\""), .direct("Why did you go out the garden door?", "\"It was closer to my truck. I thought I could pay at the exit register.\""), .direct("Where is your receipt?", "\"I don't have one. I think I left the gift card in my truck.\""), .direct("Did you plan to steal?", "\"No. I'm a contractor, and I buy tools from this store often. I'd never risk my account.\""), .direct("What did you do when the officer stopped you?", "\"I opened the bag and showed {OFF.him} the drills. I told {OFF.him} I'd pay.\""), .direct("What would you tell the store?", "\"I'm sorry for the confusion. I'll pay for the drills.\""), .cross("You've been charged with shoplifting before, haven't you?", "\"Yes, and I told the court I'd always pay. I didn't pay this time.\""), .cross("You walked out through a garden entrance with a bag full of drills?", "\"I did walk out with that bag, and I know how that looks.\""), .cross("No gift card was used at any register?", "\"That's what they say, and I can't prove otherwise.\""), .cross("You'll pay twelve hundred sixty dollars?", "\"Yes, I'll pay the twelve hundred sixty dollars today, in full, if the store allows.\""), .cross("You'll stay out of the store?", "\"Yes, if the manager asks me to, I'll stay out of the store for good.\"")],
        openings: ("A loss prevention officer at a hardware store who watches the floor and the cameras saw a man fill a duffel bag with four cordless drills, walk through the garden entrance, and leave without paying, and followed {D} to the lot, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say the drills were bought with a gift card and the receipt was lost. {D} did not steal anything."),
        closings: ("The camera shows a man load four drills into a duffel and walk out the garden entrance, loss prevention followed {D}, and since {PRIOR}, {DL} could not have missed what that means.", "A gift card purchase with a lost receipt is an honest sale. The State must prove {D} left without paying, and a lost receipt is how most honest shoppers end up at a counter."),
        timeline: [(0, "1 p.m.: {DL} enters the store."), (0, "1:20 p.m.: the garden door."), (0, "1:30 p.m.: the stop.")],
        identified: "A store camera.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let nursingAideNeglectAgain2 = SmallCases.make(
        key: "story.followup.nursingAideNeglectAgain2",
        category: .whiteCollar,
        headlines: ["Home Care Aide Used Client's Debit Card for Personal Bills, Family Says", "Aide From Neglect Case Faces Exploitation Charge"],
        law: "exploitationElder",
        threshold: 6,
        spec: "Knowingly used the debit card of {V}, an older adult, to obtain $2,350 by deception, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a home care agency placed {D} with {V}, an elderly client. A bank flagged $2,350 in card charges at stores and a phone company over five weeks. {V}'s card was kept in a kitchen drawer. {DL} says {V} asked {D.him} to run errands and pay bills.",
        state: [E(.document, 3, "Card Statement", "$2,350 in charges at stores and a phone account near {DL}'s home."), E(.video, 3, "Store Camera", "{D} at the register using {V}'s card.")],
        defense: [E(.statement, 1, "Errands", "{DL} says {V} asked {D.him} to pay bills.")],
        role: "Client's niece",
        exam: [.direct("How do you know {DL}?", "\"{DL} was a home care aide assigned by an agency to care for my aunt, who is elderly and lives alone.\""), .direct("What did you notice?", "\"My aunt told me {V.his} debit card was missing from the kitchen drawer, and {V.he} didn't know where it went.\""), .direct("What did the bank show?", "\"Charges totaling two thousand three hundred fifty dollars over five weeks, at stores and at a phone company.\""), .direct("What does the store camera show?", "\"{DL} at the register, using my aunt's card to pay for groceries and electronics.\""), .direct("What was the phone account?", "\"A phone account near {DL}'s home, which was paid with my aunt's card.\""), .direct("What did {DL} say?", "\"{D.He} said my aunt asked {D.him} to pay bills and run errands with the card.\""), .cross("Your aunt has memory problems?", "\"{V.He} has some memory problems, though {V.he} is clear on most days.\""), .cross("Your aunt did let {DL} use the card once?", "\"{V.He} remembers giving it once, for a grocery trip.\""), .cross("The charges weren't all at groceries?", "\"No, many were for electronics and a phone account.\""), .cross("{DL} didn't try to hide?", "\"{D.He} made no effort to hide, and used the card in plain view of the cashier.\""), .cross("The agency fired {DL}?", "\"Yes, the agency removed {D.him} from the case when we told them.\"")],
        theory: ("{D} used an elderly client's card for personal bills.", "Errands {V} asked for."),
