        mood: .wantsConviction)

    static let passwordResetAgain2 = SmallCases.make(
        key: "story.followup.passwordResetAgain2",
        category: .cyber,
        headlines: ["Course Partner's Thesis Folder Deleted at 2 A.M.", "Prior Account-Takeover Defendant Charged With Wiping Files"],
