        threshold: 6,
        spec: "Willfully and without authorization deleted data from the computer system of {V}, on {DATE}.",
        ages: 24...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a night-course partner, woke to find an entire shared project folder deleted from a cloud drive. The log showed {D}'s login at 2:07 a.m. and a bulk delete. {DL} says the drive was shared and {D.he} was cleaning duplicate files.",
        state: [E(.digital, 3, "Delete Log", "A bulk delete of 212 files under {D}'s login at 2:07 a.m."), E(.digital, 3, "Argument Messages", "A message the evening before: \"If you won't fix it my way, nobody gets it.\"")],
        defense: [E(.statement, 1, "Cleaning Up", "{DL} says {D.he} deleted duplicate files by mistake.")],
        role: "Victim",
        exam: [.direct("What did you find that morning?", "\"I woke up and found that our entire shared project folder on the cloud drive had been deleted.\""), .direct("Who had access to the folder?", "\"Only {DL} and I, as partners on a night-course project, which we'd worked on together for months.\""), .direct("What does the delete log show?", "\"A bulk deletion of two hundred twelve files under {DL}'s login at seven minutes past two in the morning.\""), .direct("What happened the evening before?", "\"We argued about the project, and {DL} sent me a message that said, 'If you won't fix it my way, nobody gets it.'\""), .direct("What was lost?", "\"Months of work, including drafts, data, and a final report that was due the next week.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was cleaning up duplicate files and deleted too many by mistake.\""), .cross("The files were not backed up?", "\"Only some of them were backed up, from weeks earlier, and many were lost.\""), .cross("The drive was shared?", "\"Yes, the drive was shared, and we both had full access to every file.\""), .cross("{DL} offered to help restore?", "\"After I confronted {D.him}, {D.he} said so, but {D.he} didn't actually help.\""), .cross("{DL} wrote the message in anger?", "\"I believe so, and the message was clear about what {D.he} intended.\""), .cross("You can't say {DL}'s intent?", "\"No, only what the log and the message show.\"")],
        theory: ("{D} wiped a partner's work after a fight.", "A cleanup that went too far."),
        allocution: "\"I was angry with my project partner, and I deleted files in the shared drive when I was cleaning duplicates at two in the morning. I didn't mean to delete the whole folder. I've been in this courtroom before about a password, and I'll help restore everything.\"",
